/* 0.16.67 축제 이야기 — made by tools/editorial/compile_festival_story.cjs from tools/editorial/festival_k/*.md. Do not edit here:
 * edit the manuscripts (the story workbench), then run the tool. */
window.CRPGFestivalStory={"version":1,"chains":{"EVT_CHUSEOK_ISK_1":{"festival":"CHUSEOK","route":"ISK","part":1,"title":"보름달이 뜨는 날","map":"MAP_LY_DETAIL_NORTH_GATE","items":[{"t":"scene","name":"왕생당"},{"id":"EVT_CHUSEOK_ISK_1_001","t":"narr","who":"","text":"가을 저녁. 왕생당 앞에 밤 한 바구니가 놓여 있다. 호두가 쪼그려 앉아 하나씩 세고 있다."},{"id":"EVT_CHUSEOK_ISK_1_002","t":"line","who":"호두","text":"마흔둘, 마흔셋… {PLAYER_NAME}! 마침 잘 왔어. 이거 손님 댁에서 보낸 건데, 축월절이라고 고맙다는 인사래. 너희 동네에도 축월절 있어?"},{"t":"choice","group":"EVT_CHUSEOK_ISK_1_C1","opts":[{"id":"EVT_CHUSEOK_ISK_1_003","label":"축월절은 없고, 추석이 있어. 한가위라고도 해.","items":[{"id":"EVT_CHUSEOK_ISK_1_004","t":"line","who":"호두","text":"한가위? 이름이 크다. 뭐가 그렇게 큰데?"},{"id":"EVT_CHUSEOK_ISK_1_005","t":"say","who":"주인공","text":"달이 제일 크게 뜨는 날이야. 음력 팔월 보름."}]},{"id":"EVT_CHUSEOK_ISK_1_006","label":"비슷한 게 있어. 우리는 추석이라고 불러.","items":[{"id":"EVT_CHUSEOK_ISK_1_007","t":"line","who":"호두","text":"추석. 가을 저녁이라는 뜻이야? 운치 있는데."},{"id":"EVT_CHUSEOK_ISK_1_008","t":"say","who":"주인공","text":"맞아. 보름달이 제일 크게 뜨는 날이야."}]}]},{"id":"EVT_CHUSEOK_ISK_1_009","t":"line","who":"호두","text":"오~ 보름달 보고 뭐 하는데? 소원 빌어? 축월절이랑 똑같네."},{"id":"EVT_CHUSEOK_ISK_1_010","t":"say","who":"주인공","text":"소원도 빌지. 근데 제일 큰 건 차례랑 성묘야."},{"id":"EVT_CHUSEOK_ISK_1_011","t":"line","who":"호두","text":"차례? 성묘?"},{"id":"EVT_CHUSEOK_ISK_1_012","t":"narr","who":"","text":"호두의 눈이 반짝인다. 왕생당 당주의 눈이다."},{"id":"EVT_CHUSEOK_ISK_1_013","t":"say","who":"주인공","text":"차례는 돌아가신 조상님께 음식을 차려 올리는 거야. 성묘는 산소에 찾아가서 풀 베고 인사드리는 거고."},{"id":"EVT_CHUSEOK_ISK_1_014","t":"line","who":"호두","text":"…그거, 우리 일이잖아! 돌아가신 손님을 해마다 찾아가서 밥을 차려 드린다고? 그것도 온 가족이?"},{"id":"EVT_CHUSEOK_ISK_1_015","t":"say","who":"주인공","text":"응. 멀리 사는 친척도 그날만큼은 다 모여. 길이 엄청 막혀."},{"id":"EVT_CHUSEOK_ISK_1_016","t":"line","who":"호두","text":"길이 막힐 만큼 다들 손님을 보러 간다니… 너희 세계 사람들, 의리가 대단하네."},{"t":"scene","name":"문가의 객경"},{"id":"EVT_CHUSEOK_ISK_1_017","t":"line","who":"종려","text":"해마다 같은 날, 같은 자리에 같은 음식을 올린다… 기억을 끊지 않으려는 방법으로는 훌륭하군."},{"id":"EVT_CHUSEOK_ISK_1_018","t":"narr","who":"","text":"언제 왔는지, 문가에서 종려가 밤 하나를 집어 들고 있다."},{"id":"EVT_CHUSEOK_ISK_1_019","t":"say","who":"주인공","text":"종려 씨, 리월에도 그런 게 있어요?"},{"id":"EVT_CHUSEOK_ISK_1_020","t":"line","who":"종려","text":"있지. 다만 리월 사람들은 보통 떠난 이를 바다와 하늘로 보내지. 자네 고향은 곁에 두는 쪽이로군. 어느 쪽이 옳다고는 못 하겠네. 둘 다 잊지 않으려는 것이니."},{"id":"EVT_CHUSEOK_ISK_1_021","t":"line","who":"호두","text":"좋아, 결정! 왕생당에서 차례상을 차려 보자. 리월식 말고 {PLAYER_NAME}식으로. 순서는 네가 알려 줘."},{"t":"choice","group":"EVT_CHUSEOK_ISK_1_C2","opts":[{"id":"EVT_CHUSEOK_ISK_1_022","label":"그게… 나도 제대로 차려 본 적은 없어. 늘 어머니가 하셨거든.","items":[{"id":"EVT_CHUSEOK_ISK_1_023","t":"line","who":"호두","text":"그럼 기억나는 만큼만. 모르는 건 종려 선생이 아시겠지."},{"id":"EVT_CHUSEOK_ISK_1_024","t":"line","who":"종려","text":"남의 집 제사상까지는 모르네. …하지만 사람들이 상을 차리는 이치라면, 조금은."}]},{"id":"EVT_CHUSEOK_ISK_1_025","label":"해 보자. 틀려도 조상님이 봐주시겠지.","items":[{"id":"EVT_CHUSEOK_ISK_1_026","t":"line","who":"호두","text":"히히, 그 말 좋다. 손님들은 대체로 너그러우셔."}]}]},{"id":"EVT_CHUSEOK_ISK_1_027","t":"narr","who":"","text":"호두가 밤 바구니를 번쩍 든다. 마흔세 개째 밤이 굴러떨어지고, 종려가 그것을 주워 바구니에 다시 넣는다."}]},"EVT_CHUSEOK_ISK_2":{"festival":"CHUSEOK","route":"ISK","part":2,"title":"차례상 앞에서","map":"MAP_LY_DETAIL_NORTH_GATE","items":[{"t":"scene","name":"차례상"},{"id":"EVT_CHUSEOK_ISK_2_001","t":"narr","who":"","text":"왕생당 안쪽 방. 긴 상 하나가 펴졌다. 며칠 동안 모아 온 것들이 그 옆에 쌓여 있다. 사과, 생선, 고기, 무, 버섯, 찐빵."},{"id":"EVT_CHUSEOK_ISK_2_002","t":"line","who":"호두","text":"자, 재료는 다 모였어. 이제 어디에 뭘 놓아? 아무 데나 놓으면 안 되는 거지?"},{"t":"choice","group":"EVT_CHUSEOK_ISK_2_C1","opts":[{"id":"EVT_CHUSEOK_ISK_2_003","label":"홍동백서. 빨간 과일은 동쪽, 하얀 건 서쪽.","items":[{"id":"EVT_CHUSEOK_ISK_2_004","t":"line","who":"호두","text":"오호. 그럼 동쪽이 어디야? 이 방 기준? 리월항 기준?"},{"id":"EVT_CHUSEOK_ISK_2_005","t":"say","who":"주인공","text":"…상 기준으로, 조상님 쪽에서 봤을 때 오른쪽."}]},{"id":"EVT_CHUSEOK_ISK_2_006","label":"조율이시. 대추, 밤, 배, 감 순서야.","items":[{"id":"EVT_CHUSEOK_ISK_2_007","t":"line","who":"호두","text":"대추는 없는데? 배랑 감도 없고. 밤은 마흔세 개 있어."},{"id":"EVT_CHUSEOK_ISK_2_008","t":"say","who":"주인공","text":"그럼… 있는 것부터 놓자."}]}]},{"id":"EVT_CHUSEOK_ISK_2_009","t":"line","who":"종려","text":"대개 이런 순서는 그 땅에서 먼저 나는 것, 귀한 것을 앞에 두려는 마음에서 나오지. 이곳의 것으로 차리되, 마음의 순서만 지키면 되겠군."},{"id":"EVT_CHUSEOK_ISK_2_010","t":"narr","who":"","text":"셋이 상 위에 하나씩 음식을 올린다. 호두는 생선 머리 방향으로 오 분을 고민하고, 종려는 찐빵 세 개를 정확히 같은 간격으로 놓는다."},{"t":"scene","name":"절"},{"id":"EVT_CHUSEOK_ISK_2_011","t":"narr","who":"","text":"상이 다 차려졌다. 향을 피운다. 연기가 곧게 올라간다."},{"id":"EVT_CHUSEOK_ISK_2_012","t":"line","who":"호두","text":"이제 절하는 거야? 설날에 했던 그 절?"},{"id":"EVT_CHUSEOK_ISK_2_013","t":"say","who":"주인공","text":"비슷해. 근데 이번엔 두 번 해."},{"id":"EVT_CHUSEOK_ISK_2_014","t":"narr","who":"","text":"{PLAYER_NAME}이 상 앞에 선다. 손을 겹쳐 올리고, 무릎을 꿇는다. 그런데 고개를 숙인 채로, 한참 일어나지 않는다."},{"id":"EVT_CHUSEOK_ISK_2_015","t":"line","who":"호두","text":"…{PLAYER_NAME}?"},{"t":"choice","group":"EVT_CHUSEOK_ISK_2_C2","opts":[{"id":"EVT_CHUSEOK_ISK_2_016","label":"괜찮아. 그냥… 우리 집 상도 지금쯤 이렇게 차려져 있겠다 싶어서.","items":[{"id":"EVT_CHUSEOK_ISK_2_017","t":"line","who":"호두","text":"…응."}]},{"id":"EVT_CHUSEOK_ISK_2_018","label":"나 없이도 잘 차렸겠지. 어머니가 손이 빠르시거든.","items":[{"id":"EVT_CHUSEOK_ISK_2_019","t":"line","who":"호두","text":"…그러시겠네."}]}]},{"id":"EVT_CHUSEOK_ISK_2_020","t":"narr","who":"","text":"호두가 아무 말 없이 옆에 와서 함께 무릎을 꿇는다. 장난기 없는 얼굴이다. 종려도 그 뒤에 선다."},{"id":"EVT_CHUSEOK_ISK_2_021","t":"line","who":"호두","text":"그럼 올해는 여기서 해. 네 몫까지 여기서 인사드리면, 그쪽 손님들도 알아보실 거야."},{"id":"EVT_CHUSEOK_ISK_2_022","t":"line","who":"종려","text":"기억이란 같은 날 같은 일을 반복할 때 길이 나는 법이지. 오늘 자네가 낸 길은, 내년에도 있을 걸세."},{"id":"EVT_CHUSEOK_ISK_2_023","t":"say","who":"주인공","text":"…감사합니다."},{"id":"EVT_CHUSEOK_ISK_2_024","t":"narr","who":"","text":"세 사람이 나란히 두 번 절을 올린다. 향 연기가 천천히 흩어진다. 마흔세 개의 밤이 상 위에 반듯하게 놓여 있다."}]},"EVT_CHUSEOK_ISK_3":{"festival":"CHUSEOK","route":"ISK","part":3,"title":"송편과 보름달","map":"MAP_LY_DETAIL_CHIHU","items":[{"t":"scene","name":"만민당"},{"id":"EVT_CHUSEOK_ISK_3_001","t":"narr","who":"","text":"만민당 탁자 위에 하얀 반죽 덩이와 깨, 콩, 밤으로 만든 소가 그릇마다 담겨 있다. 향릉이 반죽을 떼어 손바닥에 굴린다."},{"id":"EVT_CHUSEOK_ISK_3_002","t":"line","who":"향릉","text":"이렇게 동그랗게 해서, 소를 넣고, 반달 모양으로 오므리는 거지? 이름이 송편이랬나?"},{"t":"choice","group":"EVT_CHUSEOK_ISK_3_C1","opts":[{"id":"EVT_CHUSEOK_ISK_3_003","label":"맞아. 그리고 솔잎을 깔고 쪄. 솔잎 향이 배야 진짜야.","items":[{"id":"EVT_CHUSEOK_ISK_3_004","t":"line","who":"향릉","text":"솔잎? 그건 없는데… 대신 청심 잎을 깔아 볼까? 향은 이쪽이 더 좋을걸!"}]},{"id":"EVT_CHUSEOK_ISK_3_005","label":"예쁘게 빚으면 좋은 짝을 만난다는 말이 있어.","items":[{"id":"EVT_CHUSEOK_ISK_3_006","t":"line","who":"향릉","text":"진짜? 그럼 다들 진지하게 빚겠는데?"}]}]},{"id":"EVT_CHUSEOK_ISK_3_007","t":"narr","who":"","text":"그 말을 듣고 행추가 슬쩍 중운 쪽을 본다. 중운의 송편은 하나같이 반듯하다. 반죽이 손에 달라붙지도 않는다."},{"id":"EVT_CHUSEOK_ISK_3_008","t":"line","who":"행추","text":"흐음~ 중운. 너 송편 엄청 잘 빚는다? 누구 좋은 사람이라도 생각하는 거야?"},{"id":"EVT_CHUSEOK_ISK_3_009","t":"line","who":"중운","text":"…손이 차가워서 반죽이 안 붙을 뿐이야."},{"id":"EVT_CHUSEOK_ISK_3_010","t":"line","who":"행추","text":"그럼 좋은 짝은 체질 덕분이네."},{"id":"EVT_CHUSEOK_ISK_3_011","t":"line","who":"중운","text":"그런 뜻 아니야!"},{"t":"choice","group":"EVT_CHUSEOK_ISK_3_C2","opts":[{"id":"EVT_CHUSEOK_ISK_3_012","label":"내 건 터졌어.","items":[{"id":"EVT_CHUSEOK_ISK_3_013","t":"line","who":"향릉","text":"괜찮아, 터진 것도 맛있어! 소가 밖으로 나와서 오히려 더 고소해."}]},{"id":"EVT_CHUSEOK_ISK_3_014","label":"중운 거 하나만 바꿔 먹자.","items":[{"id":"EVT_CHUSEOK_ISK_3_015","t":"line","who":"중운","text":"…하나만이야."}]}]},{"t":"scene","name":"부두의 밤"},{"t":"move","fromId":"MAP_LY_DETAIL_CHIHU","toId":"MAP_LY_DETAIL_WHARF"},{"id":"EVT_CHUSEOK_ISK_3_016","t":"narr","who":"","text":"밤. 리월항 부두. 바다 위로 커다란 보름달이 떠 있다. 쪄 낸 송편을 하나씩 들고, 다들 난간에 기대어 선다."},{"id":"EVT_CHUSEOK_ISK_3_017","t":"line","who":"향릉","text":"와… 진짜 크다. 축월절 달보다 커 보여."},{"id":"EVT_CHUSEOK_ISK_3_018","t":"say","who":"주인공","text":"한가위니까. 이제 소원 빌면 돼."},{"id":"EVT_CHUSEOK_ISK_3_019","t":"line","who":"행추","text":"소원은 말하면 안 이뤄진다며?"},{"id":"EVT_CHUSEOK_ISK_3_020","t":"say","who":"주인공","text":"그건 생일 촛불이고. 보름달한테는 말해도 돼."},{"id":"EVT_CHUSEOK_ISK_3_021","t":"line","who":"향릉","text":"그럼 나 먼저! 내년 추석에도 다 같이 송편 빚기! 그리고 누룽지가 고추를 좀 더 좋아하기!"},{"id":"EVT_CHUSEOK_ISK_3_022","t":"line","who":"중운","text":"…올해 겨울에도, 무사히."},{"id":"EVT_CHUSEOK_ISK_3_023","t":"line","who":"행추","text":"난 비밀. 소설 속 협객은 소원을 말하지 않거든."},{"id":"EVT_CHUSEOK_ISK_3_024","t":"line","who":"향릉","text":"{PLAYER_NAME}은?"},{"t":"choice","group":"EVT_CHUSEOK_ISK_3_C3","opts":[{"id":"EVT_CHUSEOK_ISK_3_025","label":"집에 있는 사람들도, 지금 같은 달 보고 있으면 좋겠다.","items":[{"id":"EVT_CHUSEOK_ISK_3_026","t":"line","who":"향릉","text":"…보고 있을 거야. 이렇게 큰데, 못 볼 리가 없잖아."}]},{"id":"EVT_CHUSEOK_ISK_3_027","label":"내년에도 여기서 송편 먹기.","items":[{"id":"EVT_CHUSEOK_ISK_3_028","t":"line","who":"행추","text":"그거 내 소원이랑 비슷한데. 아, 말해 버렸다."}]}]},{"id":"EVT_CHUSEOK_ISK_3_029","t":"narr","who":"","text":"달빛이 바다 위로 길게 깔린다. 손에 든 송편이 아직 따뜻하다. 터진 쪽에서 깨 냄새가 났다."}]},"EVT_CHUSEOK_TRV_1":{"festival":"CHUSEOK","route":"TRV","part":1,"title":"또 그 세계","map":"MAP_LY_DETAIL_WHARF","items":[{"t":"scene","name":"달빛"},{"id":"EVT_CHUSEOK_TRV_1_001","t":"narr","who":"","text":"밤길. 하늘에 둥근 달이 떠 있다. 그 달빛이 갑자기 땅까지 내려와 하얗게 번진다."},{"id":"EVT_CHUSEOK_TRV_1_002","t":"line","who":"페이몬","text":"여, 여행자! 이 느낌… 어디서 겪어 본 것 같지 않아? 눈앞이 하얘지는 거!"},{"id":"EVT_CHUSEOK_TRV_1_003","t":"say","who":"주인공","text":"페이몬, 손."},{"id":"EVT_CHUSEOK_TRV_1_004","t":"narr","who":"","text":"빛이 걷힌다. 파도 소리. 리월항 부두다. 그런데 바다 위에 뜬 달이 지나치게 크다. 그리고 부두 난간에 기대 있던 사람 하나가 이쪽을 보고 손을 든다."},{"id":"EVT_CHUSEOK_TRV_1_005","t":"line","who":"이세계인","text":"어? 또 왔네? …아니, 처음인가? 아무튼 마침 잘 왔어."},{"t":"choice","group":"EVT_CHUSEOK_TRV_1_C1","opts":[{"id":"EVT_CHUSEOK_TRV_1_006","label":"우리를 알아?","items":[{"id":"EVT_CHUSEOK_TRV_1_007","t":"line","who":"이세계인","text":"알지. 내가 원래 살던 세계에선 너희 엄청 유명하거든. 나는 그 세계에서 여기로 굴러떨어진 사람이고. 출근하다가."}]},{"id":"EVT_CHUSEOK_TRV_1_008","label":"또 너구나.","items":[{"id":"EVT_CHUSEOK_TRV_1_009","t":"line","who":"이세계인","text":"또 나야. 반가워. 이번엔 반죽 말고 다른 일 시킬게."}]}]},{"id":"EVT_CHUSEOK_TRV_1_010","t":"line","who":"페이몬","text":"여기 어디야? 리월항 맞지? 근데 달이 왜 이렇게 커?"},{"id":"EVT_CHUSEOK_TRV_1_011","t":"line","who":"이세계인","text":"내일이 추석이거든. 내 고향 명절이야. 한가위라고도 해. 달이 일 년 중에 제일 크게 뜨는 날."},{"t":"scene","name":"한가위"},{"id":"EVT_CHUSEOK_TRV_1_012","t":"line","who":"페이몬","text":"명절이면 맛있는 거 있지? 그치?"},{"id":"EVT_CHUSEOK_TRV_1_013","t":"line","who":"이세계인","text":"송편이 있어. 쌀 반죽에 깨나 콩을 넣고 반달 모양으로 빚어서 찌는 떡. 그리고 차례상."},{"id":"EVT_CHUSEOK_TRV_1_014","t":"say","who":"주인공","text":"차례상?"},{"id":"EVT_CHUSEOK_TRV_1_015","t":"line","who":"이세계인","text":"돌아가신 조상님께 음식을 차려 올리는 거야. 해마다 같은 날에. 멀리 사는 가족도 그날은 다 모이고."},{"id":"EVT_CHUSEOK_TRV_1_016","t":"line","who":"페이몬","text":"가족이 다 모인다… 여행자."},{"id":"EVT_CHUSEOK_TRV_1_017","t":"say","who":"주인공","text":"응."},{"id":"EVT_CHUSEOK_TRV_1_018","t":"narr","who":"","text":"여행자가 바다 쪽을 본다. 아주 멀리, 달 아래 어딘가를. 이세계인은 그 시선을 따라가다가, 일부러 소리를 높인다."},{"id":"EVT_CHUSEOK_TRV_1_019","t":"line","who":"이세계인","text":"그래서! 왕생당에서 차례상을 차리기로 했어. 호두가 엄청 신났거든. 재료 모을 손이 필요해. 사과, 생선, 고기, 무… 여행자는 강하니까 사냥 담당. 페이몬은…"},{"id":"EVT_CHUSEOK_TRV_1_020","t":"line","who":"페이몬","text":"시식 담당!"},{"id":"EVT_CHUSEOK_TRV_1_021","t":"line","who":"이세계인","text":"그런 담당은 없어."},{"id":"EVT_CHUSEOK_TRV_1_022","t":"narr","who":"","text":"커다란 달 아래에서, 셋이 왕생당 쪽으로 걸어간다. 부두의 등불이 하나씩 켜진다."}]},"EVT_CHUSEOK_TRV_2":{"festival":"CHUSEOK","route":"TRV","part":2,"title":"차례상과 두 가족","map":"MAP_LY_DETAIL_NORTH_GATE","items":[{"t":"scene","name":"차례상"},{"id":"EVT_CHUSEOK_TRV_2_001","t":"narr","who":"","text":"왕생당 안쪽 방. 여행자가 잡아 온 고기와 생선이 상 위에 놓이고, 호두가 마흔세 개의 밤을 반듯하게 쌓는다."},{"id":"EVT_CHUSEOK_TRV_2_002","t":"line","who":"호두","text":"홍동백서! 빨간 건 동쪽, 하얀 건 서쪽! 이세계인이 알려 줬어. 이 당주님 벌써 다 외웠다구."},{"id":"EVT_CHUSEOK_TRV_2_003","t":"line","who":"이세계인","text":"그 동쪽이 어딘지는 아직 합의가 안 됐지만."},{"id":"EVT_CHUSEOK_TRV_2_004","t":"line","who":"페이몬","text":"이 생선은 왜 머리가 이쪽이야? 저쪽 보면 안 돼?"},{"id":"EVT_CHUSEOK_TRV_2_005","t":"line","who":"호두","text":"그건 오 분 동안 고민해서 정한 거라 건드리면 안 돼."},{"id":"EVT_CHUSEOK_TRV_2_006","t":"say","who":"주인공","text":"무슨 순서인지 몰라도, 다들 진지하네."},{"id":"EVT_CHUSEOK_TRV_2_007","t":"line","who":"종려","text":"순서를 지키는 일은, 그 순서를 알려 준 사람을 기억하는 일이기도 하지."},{"id":"EVT_CHUSEOK_TRV_2_008","t":"narr","who":"","text":"문가에 종려가 서 있다. 여행자를 한 번 보고, 상을 한 번 본다."},{"id":"EVT_CHUSEOK_TRV_2_009","t":"line","who":"종려","text":"먼 데서 온 손님이 또 있군. 자네도 차례를 올리겠나?"},{"t":"choice","group":"EVT_CHUSEOK_TRV_2_C1","opts":[{"id":"EVT_CHUSEOK_TRV_2_010","label":"나는… 올릴 조상이 없어.","items":[{"id":"EVT_CHUSEOK_TRV_2_011","t":"line","who":"종려","text":"조상이 아니어도 괜찮네. 지금 곁에 없는 사람이라면 누구든."}]},{"id":"EVT_CHUSEOK_TRV_2_012","label":"해도 돼요?","items":[{"id":"EVT_CHUSEOK_TRV_2_013","t":"line","who":"종려","text":"마음을 놓을 자리가 상 위에 하나 더 있다고 해서 무거워지지는 않지."}]}]},{"t":"scene","name":"절"},{"id":"EVT_CHUSEOK_TRV_2_014","t":"narr","who":"","text":"이세계인이 먼저 상 앞에 선다. 손을 겹쳐 올리고, 두 번 절한다. 고개를 숙인 채로 오래 있다가, 천천히 일어난다."},{"id":"EVT_CHUSEOK_TRV_2_015","t":"line","who":"이세계인","text":"…우리 집 상도 지금쯤 차려져 있겠지. 나 없이."},{"id":"EVT_CHUSEOK_TRV_2_016","t":"line","who":"페이몬","text":"…"},{"id":"EVT_CHUSEOK_TRV_2_017","t":"line","who":"이세계인","text":"여행자도 해. 찾는 사람 있다며."},{"id":"EVT_CHUSEOK_TRV_2_018","t":"narr","who":"","text":"여행자가 상 앞에 선다. 옆에서 페이몬이 처음으로 조용하다."},{"id":"EVT_CHUSEOK_TRV_2_019","t":"say","who":"주인공","text":"(내 가족. 같이 떨어진 사람. 지금 어디 있든, 같은 달 아래에.)"},{"id":"EVT_CHUSEOK_TRV_2_020","t":"narr","who":"","text":"두 번 절한다. 향 연기가 곧게 올라간다."},{"id":"EVT_CHUSEOK_TRV_2_021","t":"line","who":"페이몬","text":"…여행자."},{"id":"EVT_CHUSEOK_TRV_2_022","t":"say","who":"주인공","text":"괜찮아. 생각보다, 괜찮아."},{"id":"EVT_CHUSEOK_TRV_2_023","t":"line","who":"호두","text":"좋아. 그럼 이제 산 사람 차례야. 밥 먹자! 차례 지낸 음식은 나눠 먹는 거라며?"},{"id":"EVT_CHUSEOK_TRV_2_024","t":"line","who":"이세계인","text":"맞아. 그게 제일 중요한 순서야."},{"id":"EVT_CHUSEOK_TRV_2_025","t":"line","who":"페이몬","text":"그 순서는 내가 제일 잘 지킬 수 있어!"}]},"EVT_CHUSEOK_TRV_3":{"festival":"CHUSEOK","route":"TRV","part":3,"title":"같은 달","map":"MAP_LY_DETAIL_CHIHU","items":[{"t":"scene","name":"송편"},{"id":"EVT_CHUSEOK_TRV_3_001","t":"narr","who":"","text":"만민당. 향릉이 반죽을 나눠 주고, 다들 손바닥 위에서 반달을 빚는다. 페이몬의 송편은 이상하게 별 모양이다."},{"id":"EVT_CHUSEOK_TRV_3_002","t":"line","who":"향릉","text":"페이몬 건 반달이 아니라… 별이네?"},{"id":"EVT_CHUSEOK_TRV_3_003","t":"line","who":"페이몬","text":"이게 더 예쁘잖아! 예쁘게 빚으면 좋은 짝을 만난다며!"},{"id":"EVT_CHUSEOK_TRV_3_004","t":"line","who":"이세계인","text":"그 말은 어디서 들었어?"},{"id":"EVT_CHUSEOK_TRV_3_005","t":"line","who":"페이몬","text":"너한테! 아까!"},{"id":"EVT_CHUSEOK_TRV_3_006","t":"say","who":"주인공","text":"나도 하나 빚어 볼게."},{"id":"EVT_CHUSEOK_TRV_3_007","t":"narr","who":"","text":"여행자의 송편은 단단하고 반듯하다. 이세계인이 그것을 보고 감탄하다가 자기 손의 터진 송편을 슬쩍 뒤로 감춘다."},{"t":"scene","name":"부두의 밤"},{"t":"move","fromId":"MAP_LY_DETAIL_CHIHU","toId":"MAP_LY_DETAIL_WHARF"},{"id":"EVT_CHUSEOK_TRV_3_008","t":"narr","who":"","text":"밤. 부두 난간. 바다 위에 거대한 보름달. 다들 따뜻한 송편을 하나씩 들고 있다."},{"id":"EVT_CHUSEOK_TRV_3_009","t":"line","who":"이세계인","text":"이제 소원 빌면 돼. 보름달한테는 말해도 이뤄져."},{"id":"EVT_CHUSEOK_TRV_3_010","t":"line","who":"페이몬","text":"나 먼저! 내년에도 송편 먹기! 아니, 매일 먹기!"},{"id":"EVT_CHUSEOK_TRV_3_011","t":"line","who":"이세계인","text":"여행자는?"},{"t":"choice","group":"EVT_CHUSEOK_TRV_3_C1","opts":[{"id":"EVT_CHUSEOK_TRV_3_012","label":"찾는 사람을 꼭 찾기.","items":[{"id":"EVT_CHUSEOK_TRV_3_013","t":"line","who":"이세계인","text":"…그거 좋다. 나도 같은 걸로 할래. 찾는 사람은 다르지만."}]},{"id":"EVT_CHUSEOK_TRV_3_014","label":"너도 언젠가 집에 돌아가기.","items":[{"id":"EVT_CHUSEOK_TRV_3_015","t":"line","who":"이세계인","text":"그건… 고마워. 근데 요즘은 반반이야. 여기도 이제 꽤 집 같거든."}]}]},{"id":"EVT_CHUSEOK_TRV_3_016","t":"narr","who":"","text":"바다 위 하늘이 하얗게 번지기 시작한다. 달빛이 아니라, 처음 넘어올 때 본 그 빛이다."},{"id":"EVT_CHUSEOK_TRV_3_017","t":"line","who":"이세계인","text":"시간 됐나 보네. 잠깐, 이거."},{"id":"EVT_CHUSEOK_TRV_3_018","t":"narr","who":"","text":"이세계인이 청심 잎에 싼 송편 꾸러미를 건넨다. 별 모양 하나, 반듯한 것 하나, 터진 것 하나."},{"id":"EVT_CHUSEOK_TRV_3_019","t":"line","who":"이세계인","text":"터진 건 내 거야. 맛은 제일 좋아. 즐거운 한가위 보내, 여행자. 페이몬도."},{"id":"EVT_CHUSEOK_TRV_3_020","t":"say","who":"주인공","text":"너도. 즐거운 한가위."},{"id":"EVT_CHUSEOK_TRV_3_021","t":"line","who":"페이몬","text":"내년에도 불러 줘! 꼭!"},{"t":"scene","name":"원래의 길"},{"id":"EVT_CHUSEOK_TRV_3_022","t":"narr","who":"","text":"눈을 뜬다. 원래 걷던 밤길이다. 하늘의 달은 평소 크기로 돌아와 있다."},{"id":"EVT_CHUSEOK_TRV_3_023","t":"line","who":"페이몬","text":"…또 꿈이었나?"},{"id":"EVT_CHUSEOK_TRV_3_024","t":"narr","who":"","text":"여행자의 손에 청심 잎 꾸러미가 들려 있다. 아직 따뜻하다."},{"id":"EVT_CHUSEOK_TRV_3_025","t":"say","who":"주인공","text":"같은 달이야. 거기서도 보고 있겠지."},{"id":"EVT_CHUSEOK_TRV_3_026","t":"line","who":"페이몬","text":"헤헤. 그럼 우리도 같이 보자. 송편 먹으면서!"}]},"EVT_SEOLLAL_ISK_1":{"festival":"SEOLLAL","route":"ISK","part":1,"title":"설날이 뭐야?","map":"MAP_LY_DETAIL_CHIHU","items":[{"t":"scene","name":"만민당 앞"},{"id":"EVT_SEOLLAL_ISK_1_001","t":"narr","who":"","text":"리월항의 겨울 오후. 만민당 화덕에서 김이 끊이지 않는다. 처마 끝마다 붉은 등이 하나씩 늘어 간다."},{"id":"EVT_SEOLLAL_ISK_1_002","t":"line","who":"향릉","text":"{PLAYER_NAME}! 마침 잘 왔어. 해등절 차림표를 짜는 중인데, 하나만 맛봐 줄래?"},{"t":"choice","group":"EVT_SEOLLAL_ISK_1_C1","opts":[{"id":"EVT_SEOLLAL_ISK_1_003","label":"맛보는 건 자신 있어. 회사에서 회식 메뉴 고르는 게 내 유일한 특기였거든.","items":[{"id":"EVT_SEOLLAL_ISK_1_004","t":"line","who":"향릉","text":"회식? 다 같이 모여서 먹는 거지? 그럼 딱이네!"}]},{"id":"EVT_SEOLLAL_ISK_1_005","label":"벌써 해등절 준비야?","items":[{"id":"EVT_SEOLLAL_ISK_1_006","t":"line","who":"향릉","text":"아직 좀 남았어. 그래도 등을 걸기 시작하면 다들 배가 고파지거든!"}]}]},{"id":"EVT_SEOLLAL_ISK_1_007","t":"narr","who":"","text":"향릉이 국자로 국물을 한 숟갈 떠서 내민다. 뜨겁고, 달큰하고, 어딘가 익숙한 냄새가 난다."},{"id":"EVT_SEOLLAL_ISK_1_008","t":"line","who":"향릉","text":"어때? 이번엔 누룽지가 고추를 덜 넣자고 해서, 정말 조금만 넣었어."},{"id":"EVT_SEOLLAL_ISK_1_009","t":"say","who":"주인공","text":"맛있다. 근데 이 냄새… 우리 동네 설날 냄새랑 비슷해."},{"id":"EVT_SEOLLAL_ISK_1_010","t":"line","who":"향릉","text":"설날? 그게 뭐야? 너희 동네 해등절이야?"},{"id":"EVT_SEOLLAL_ISK_1_011","t":"say","who":"주인공","text":"비슷해. 새해 첫날이야. 해가 바뀌면 가족이 다 모여서 떡국을 먹어."},{"id":"EVT_SEOLLAL_ISK_1_012","t":"line","who":"향릉","text":"떡… 국? 떡을 국에 넣는다고? 쫄깃한 걸 국물에? 그럼 퍼지지 않아?"},{"id":"EVT_SEOLLAL_ISK_1_013","t":"say","who":"주인공","text":"얇게 썰어서 넣으면 괜찮아. 떡국 한 그릇 먹으면 한 살 먹는 거라고 했어."},{"id":"EVT_SEOLLAL_ISK_1_014","t":"line","who":"향릉","text":"한 그릇에 한 살? 그럼 두 그릇 먹으면 두 살이야?"},{"id":"EVT_SEOLLAL_ISK_1_015","t":"say","who":"주인공","text":"어릴 땐 빨리 크고 싶어서 진짜 두 그릇 먹었어. 지금은 한 그릇도 무서워."},{"id":"EVT_SEOLLAL_ISK_1_016","t":"narr","who":"","text":"향릉이 웃음을 터뜨린다. 옆 탁자에서 책을 펼쳐 두고 있던 행추가 고개를 든다."},{"id":"EVT_SEOLLAL_ISK_1_017","t":"line","who":"행추","text":"흐음~ 새해에 나이를 먹는 국이라니, 재미있네. 그 설날이라는 거, 국 말고 또 뭘 해?"},{"t":"choice","group":"EVT_SEOLLAL_ISK_1_C2","opts":[{"id":"EVT_SEOLLAL_ISK_1_018","label":"어른들한테 절을 해. 세배라고 하는데, 그러면 어른들이 세뱃돈을 줘.","items":[{"id":"EVT_SEOLLAL_ISK_1_019","t":"line","who":"행추","text":"절을 하면 돈을 준다고? …중운이 들으면 한동안 절만 하고 다니겠는데."}]},{"id":"EVT_SEOLLAL_ISK_1_020","label":"윷놀이를 해. 나무 막대 네 개를 던져서 말을 옮기는 놀이야.","items":[{"id":"EVT_SEOLLAL_ISK_1_021","t":"line","who":"행추","text":"막대를 던져 말을 옮긴다… 무협 소설에 나오는 진법 같은 건가?"},{"id":"EVT_SEOLLAL_ISK_1_022","t":"say","who":"주인공","text":"그런 거 아니야. 온 가족이 모여서 소리 지르는 놀이야."},{"id":"EVT_SEOLLAL_ISK_1_023","t":"line","who":"행추","text":"그거야말로 진법이지. 사람 마음을 흔드는 진법."}]}]},{"id":"EVT_SEOLLAL_ISK_1_024","t":"line","who":"행추","text":"좋아, 리월에서도 해 보자. 해등절이랑 날짜도 가깝잖아."},{"id":"EVT_SEOLLAL_ISK_1_025","t":"line","who":"향릉","text":"찬성! 떡국은 내가 맡을게. {PLAYER_NAME}, 떡은 어떻게 만들어?"},{"id":"EVT_SEOLLAL_ISK_1_026","t":"say","who":"주인공","text":"…사 먹었는데."},{"id":"EVT_SEOLLAL_ISK_1_027","t":"line","who":"향릉","text":"사 먹었다고?! 그럼 같이 만들어 보자. 쌀이랑 물이 있으면 어떻게든 되겠지!"},{"id":"EVT_SEOLLAL_ISK_1_028","t":"narr","who":"","text":"만민당 화덕 위로 김이 피어오른다. 리월항의 처마 끝에서, 낯선 이름의 명절 하나가 준비되기 시작했다."}]},"EVT_SEOLLAL_ISK_2":{"festival":"SEOLLAL","route":"ISK","part":2,"title":"세배와 세뱃돈","map":"MAP_LY_DETAIL_NORTH_GATE","items":[{"t":"scene","name":"왕생당"},{"id":"EVT_SEOLLAL_ISK_2_001","t":"narr","who":"","text":"왕생당 앞마당. 행추가 소문을 냈는지, 호두가 문 앞에서 팔짱을 끼고 기다리고 있다."},{"id":"EVT_SEOLLAL_ISK_2_002","t":"line","who":"호두","text":"왔다, 왔어! 절 한 번에 모라를 받는 비법이 있다며? 이 당주님한테도 알려 줘야지."},{"t":"choice","group":"EVT_SEOLLAL_ISK_2_C1","opts":[{"id":"EVT_SEOLLAL_ISK_2_003","label":"비법이 아니라 예절이야. 그리고 받는 건 아랫사람이야.","items":[{"id":"EVT_SEOLLAL_ISK_2_004","t":"line","who":"호두","text":"어라? 그럼 이 당주님은 받는 쪽이야, 주는 쪽이야? …나이로 따지면 좀 애매한데."}]},{"id":"EVT_SEOLLAL_ISK_2_005","label":"소문이 벌써 왕생당까지 갔어?","items":[{"id":"EVT_SEOLLAL_ISK_2_006","t":"line","who":"호두","text":"비운 상회 둘째 도련님 입은 리월항에서 제일 빠르거든. 히히."}]}]},{"id":"EVT_SEOLLAL_ISK_2_007","t":"narr","who":"","text":"마당 한쪽에서 중운이 어색하게 서 있다. 행추에게 끌려온 얼굴이다."},{"id":"EVT_SEOLLAL_ISK_2_008","t":"line","who":"중운","text":"행추가 그러는데… 절을 제대로 하면 복이 들어온다고. 사실이야?"},{"id":"EVT_SEOLLAL_ISK_2_009","t":"say","who":"주인공","text":"복은 모르겠고, 세뱃돈은 들어와."},{"id":"EVT_SEOLLAL_ISK_2_010","t":"line","who":"중운","text":"…그럼 제대로 배워 둬야겠군."},{"t":"scene","name":"세배 연습"},{"id":"EVT_SEOLLAL_ISK_2_011","t":"narr","who":"","text":"{PLAYER_NAME}이 마당 한가운데 선다. 손을 겹쳐 이마에 대고, 무릎을 꿇고, 천천히 고개를 숙인다."},{"id":"EVT_SEOLLAL_ISK_2_012","t":"say","who":"주인공","text":"이렇게. 손은 겹쳐서 올리고, 무릎 꿇고, 천천히 숙여. 일어날 때도 천천히."},{"id":"EVT_SEOLLAL_ISK_2_013","t":"line","who":"호두","text":"오~ 생각보다 근사한데? 장례 의식이랑 비슷한 데도 있고. 우리 손님들한테도 해 드릴까?"},{"id":"EVT_SEOLLAL_ISK_2_014","t":"say","who":"주인공","text":"그건 좀… 산 사람한테 하는 거야."},{"id":"EVT_SEOLLAL_ISK_2_015","t":"line","who":"호두","text":"알아, 알아. 농담이야. 반만."},{"id":"EVT_SEOLLAL_ISK_2_016","t":"narr","who":"","text":"중운이 따라 하다가 너무 깊이 숙여 이마를 바닥에 찧는다. 호두가 배를 잡고 웃는다."},{"id":"EVT_SEOLLAL_ISK_2_017","t":"line","who":"종려","text":"좋은 절이군. 마음이 담긴 절은 소리가 나는 법이지."},{"id":"EVT_SEOLLAL_ISK_2_018","t":"narr","who":"","text":"언제 왔는지, 왕생당 문가에 종려가 서 있다. 찻잔을 든 채다."},{"id":"EVT_SEOLLAL_ISK_2_019","t":"say","who":"주인공","text":"종려 씨! 언제부터 보고 계셨어요?"},{"id":"EVT_SEOLLAL_ISK_2_020","t":"line","who":"종려","text":"처음부터. 새해 첫날에 윗사람에게 예를 올리는 풍습이라… 리월에도 오래전엔 비슷한 것이 있었네. 해등절도 처음엔 한 해를 여는 의식이었지."},{"id":"EVT_SEOLLAL_ISK_2_021","t":"say","who":"주인공","text":"그럼 종려 씨가 제일 어른이시네요. 세배 받으세요."},{"id":"EVT_SEOLLAL_ISK_2_022","t":"narr","who":"","text":"셋이 나란히 서서 절을 올린다. 종려는 고개를 끄덕이고, 소매 안을 더듬는다. 한 번, 두 번."},{"id":"EVT_SEOLLAL_ISK_2_023","t":"line","who":"종려","text":"…지갑을 두고 왔군."},{"id":"EVT_SEOLLAL_ISK_2_024","t":"line","who":"호두","text":"역시! 그럴 줄 알았어!"},{"id":"EVT_SEOLLAL_ISK_2_025","t":"say","who":"주인공","text":"괜찮아요. 세뱃돈 대신 덕담을 해 주셔도 돼요. 좋은 말 한마디요."},{"id":"EVT_SEOLLAL_ISK_2_026","t":"line","who":"종려","text":"덕담이라. 그렇다면 —"},{"id":"EVT_SEOLLAL_ISK_2_027","t":"line","who":"종려","text":"올해는 자네들이 맺는 약속마다, 지킬 수 있는 만큼만 맺기를. 그리고 맺은 것은 끝까지 지키기를."},{"id":"EVT_SEOLLAL_ISK_2_028","t":"line","who":"중운","text":"…모라보다 무거운 말이군."},{"id":"EVT_SEOLLAL_ISK_2_029","t":"line","who":"호두","text":"그래도 이 당주님은 모라가 좋은데! 좋아, 결정! 내가 세뱃돈 줄게. 중운, 이리 와서 한 번 더 절해!"},{"id":"EVT_SEOLLAL_ISK_2_030","t":"narr","who":"","text":"중운이 진지한 얼굴로 다시 무릎을 꿇는다. 이번에는 이마를 찧지 않았다."}]},"EVT_SEOLLAL_ISK_3":{"festival":"SEOLLAL","route":"ISK","part":3,"title":"한 그릇에 한 살","map":"MAP_LY_DETAIL_CHIHU","items":[{"t":"scene","name":"만민당의 밤"},{"id":"EVT_SEOLLAL_ISK_3_001","t":"narr","who":"","text":"해가 지고, 만민당 앞에 탁자가 세 개 붙었다. 하얀 국물 위에 얇게 썬 떡이 동동 떠 있다. 누룽지가 불을 지키느라 꼬리를 흔든다."},{"id":"EVT_SEOLLAL_ISK_3_002","t":"line","who":"향릉","text":"짠! 리월식 떡국이야. 쌀을 찧어서 쪄 보고, 늘여 보고, 세 번 실패하고 네 번째에 성공했어!"},{"t":"choice","group":"EVT_SEOLLAL_ISK_3_C1","opts":[{"id":"EVT_SEOLLAL_ISK_3_003","label":"실패한 세 번은 어디 갔어?","items":[{"id":"EVT_SEOLLAL_ISK_3_004","t":"line","who":"향릉","text":"…누룽지 배 속에."}]},{"id":"EVT_SEOLLAL_ISK_3_005","label":"진짜 떡국이다. 모양도 맞아.","items":[{"id":"EVT_SEOLLAL_ISK_3_006","t":"line","who":"향릉","text":"네가 말한 대로 어슷하게 썰었어. 이게 제일 어려웠다니까."}]}]},{"id":"EVT_SEOLLAL_ISK_3_007","t":"line","who":"행추","text":"한 그릇에 한 살이라고 했지? 그럼 다들 조심해서 먹어. 특히 중운."},{"id":"EVT_SEOLLAL_ISK_3_008","t":"line","who":"중운","text":"…왜 나야."},{"id":"EVT_SEOLLAL_ISK_3_009","t":"line","who":"행추","text":"너는 뜨거운 걸 먹으면 정신을 못 차리잖아. 한 살 먹기 전에 정신부터 잃을걸."},{"id":"EVT_SEOLLAL_ISK_3_010","t":"narr","who":"","text":"중운이 떡국을 앞에 두고 한참을 기다린다. 김이 다 빠질 때까지. 그사이 호두는 벌써 두 그릇째다."},{"id":"EVT_SEOLLAL_ISK_3_011","t":"line","who":"호두","text":"히히, 이 당주님은 두 살 먹을 거야. 어차피 장례식장 주인은 나이가 많아 보이는 게 장사에 좋거든."},{"id":"EVT_SEOLLAL_ISK_3_012","t":"say","who":"주인공","text":"그 논리면 종려 씨는 열 그릇 드셔야겠네요."},{"id":"EVT_SEOLLAL_ISK_3_013","t":"line","who":"종려","text":"열 그릇으로 될 나이가 아니라서, 한 그릇만 먹겠네."},{"id":"EVT_SEOLLAL_ISK_3_014","t":"narr","who":"","text":"다들 웃는다. 숟가락 소리가 이어진다. 행추가 윷 대신 젓가락 네 짝을 던져 보다가 향릉에게 혼난다."},{"t":"scene","name":"덕담"},{"id":"EVT_SEOLLAL_ISK_3_015","t":"narr","who":"","text":"그릇이 비어 갈 무렵, {PLAYER_NAME}의 숟가락이 잠깐 멈춘다."},{"id":"EVT_SEOLLAL_ISK_3_016","t":"line","who":"향릉","text":"왜? 맛이 이상해?"},{"t":"choice","group":"EVT_SEOLLAL_ISK_3_C2","opts":[{"id":"EVT_SEOLLAL_ISK_3_017","label":"아니, 맛있어. 그냥… 집에서도 지금쯤 다들 이거 먹고 있겠다 싶어서.","items":[{"id":"EVT_SEOLLAL_ISK_3_018","t":"line","who":"향릉","text":"…그렇구나."}]},{"id":"EVT_SEOLLAL_ISK_3_019","label":"아니야. 너무 맛있어서 그래. 회사 앞 식당보다 백 배 맛있어.","items":[{"id":"EVT_SEOLLAL_ISK_3_020","t":"line","who":"향릉","text":"거짓말. 눈이 빨개."}]}]},{"id":"EVT_SEOLLAL_ISK_3_021","t":"narr","who":"","text":"잠깐 말이 끊긴다. 향릉이 냄비를 들고 와서, 빈 그릇에 한 국자를 더 떠 준다."},{"id":"EVT_SEOLLAL_ISK_3_022","t":"line","who":"향릉","text":"그럼 올해는 여기서 한 살 먹으면 되잖아. 모자라면 더 줄게. 두 살 먹어도 돼."},{"id":"EVT_SEOLLAL_ISK_3_023","t":"line","who":"중운","text":"…나도 한 그릇 더. 이제 식었으니까."},{"id":"EVT_SEOLLAL_ISK_3_024","t":"line","who":"행추","text":"그럼 덕담 순서야. 설날엔 그런 걸 한다며? {PLAYER_NAME}, 네가 먼저 해."},{"id":"EVT_SEOLLAL_ISK_3_025","t":"say","who":"주인공","text":"다들, 새해 복 많이 받아."},{"id":"EVT_SEOLLAL_ISK_3_026","t":"line","who":"호두","text":"짧다! 그래도 좋아. 너도 새해 복 많이 받아. 복이 넘치면 왕생당에 맡겨. 이자는 없지만."},{"id":"EVT_SEOLLAL_ISK_3_027","t":"narr","who":"","text":"리월항 하늘 위로 첫 등불 하나가 떠오른다. 해등절보다 조금 이른, 낯선 이름의 새해였다."}]},"EVT_SEOLLAL_TRV_1":{"festival":"SEOLLAL","route":"TRV","part":1,"title":"낯선 리월","map":"MAP_LIYUE_HARBOR","items":[{"t":"scene","name":"어느 길 위"},{"id":"EVT_SEOLLAL_TRV_1_001","t":"narr","who":"","text":"바람이 멎었다. 발밑의 길이 갑자기 하얗게 빛나더니, 눈앞이 하얗게 지워졌다."},{"id":"EVT_SEOLLAL_TRV_1_002","t":"line","who":"페이몬","text":"으아악! 여, 여행자! 이거 뭐야? 눈이 안 보여!"},{"id":"EVT_SEOLLAL_TRV_1_003","t":"say","who":"주인공","text":"페이몬, 내 손 잡아."},{"id":"EVT_SEOLLAL_TRV_1_004","t":"narr","who":"","text":"빛이 걷힌다. 붉은 등이 처마마다 걸린 항구. 리월항이다. 그런데 어딘가 다르다. 문마다 낯선 글씨가 붙어 있고, 처음 보는 비단 주머니가 바람에 흔들린다."},{"id":"EVT_SEOLLAL_TRV_1_005","t":"line","who":"페이몬","text":"리월항…이지? 근데 저거 봐. 저런 장식은 처음 봐. 해등절 장식도 아니고."},{"id":"EVT_SEOLLAL_TRV_1_006","t":"say","who":"주인공","text":"공기가 달라. 우리가 있던 곳이 아니야."},{"t":"scene","name":"항구의 이세계인"},{"id":"EVT_SEOLLAL_TRV_1_007","t":"narr","who":"","text":"등을 걸던 사람 하나가 사다리 위에서 이쪽을 내려다본다. 리월 옷을 입었는데 어딘가 어색하다. 그 사람이 눈을 크게 뜨더니 사다리에서 거의 굴러 내려온다."},{"id":"EVT_SEOLLAL_TRV_1_008","t":"line","who":"이세계인","text":"어? 어어? 잠깐만. 그 망토… 그 머리… 그리고 옆에 떠 있는 그거. 혹시… 여행자? 그리고 비상식량?"},{"id":"EVT_SEOLLAL_TRV_1_009","t":"line","who":"페이몬","text":"비상식량 아니라구! 처음 보는 사람이 왜 그 말을 알아?!"},{"id":"EVT_SEOLLAL_TRV_1_010","t":"say","who":"주인공","text":"…우리를 알아?"},{"id":"EVT_SEOLLAL_TRV_1_011","t":"line","who":"이세계인","text":"안다고 해야 하나… 내가 원래 살던 세계에서는 다들 알아. 아, 이건 설명하면 길어. 나도 어느 날 눈 떠 보니까 이 세계에 와 있었거든. 회사 가다가."},{"id":"EVT_SEOLLAL_TRV_1_012","t":"line","who":"페이몬","text":"회사? 그게 어디야? 리월의 지명이야?"},{"id":"EVT_SEOLLAL_TRV_1_013","t":"line","who":"이세계인","text":"지옥 비슷한 곳. 아무튼 반가워. 진짜 실물이네."},{"t":"choice","group":"EVT_SEOLLAL_TRV_1_C1","opts":[{"id":"EVT_SEOLLAL_TRV_1_014","label":"여기가 어디야? 리월항 같은데, 조금 달라.","items":[{"id":"EVT_SEOLLAL_TRV_1_015","t":"line","who":"이세계인","text":"리월 맞아. 다만 너희가 알던 리월은 아닐 수도 있어. 여기엔 너희가 아니라 내가 굴러떨어졌으니까."}]},{"id":"EVT_SEOLLAL_TRV_1_016","label":"우리가 왜 여기 왔는지 알아?","items":[{"id":"EVT_SEOLLAL_TRV_1_017","t":"line","who":"이세계인","text":"전혀. 근데 하필 이때 온 건 운이 좋은 거야."}]}]},{"id":"EVT_SEOLLAL_TRV_1_018","t":"line","who":"이세계인","text":"며칠 뒤면 설날이거든. 내 고향 명절인데, 여기 사람들한테 알려 주는 중이야. 해등절이랑은 또 달라."},{"id":"EVT_SEOLLAL_TRV_1_019","t":"line","who":"페이몬","text":"명절? 그럼 맛있는 거 나와?"},{"id":"EVT_SEOLLAL_TRV_1_020","t":"line","who":"이세계인","text":"떡국이 나와. 떡을 넣은 국인데, 한 그릇 먹으면 한 살 먹어."},{"id":"EVT_SEOLLAL_TRV_1_021","t":"line","who":"페이몬","text":"나이를 먹는 국?! …그럼 나는 안 먹을래. 아니, 맛만 볼래."},{"id":"EVT_SEOLLAL_TRV_1_022","t":"say","who":"주인공","text":"돌아가는 방법을 찾을 때까지, 같이 있어도 될까?"},{"id":"EVT_SEOLLAL_TRV_1_023","t":"line","who":"이세계인","text":"물론이지. 마침 손이 모자랐어. 만민당에 떡 반죽이 산더미로 쌓여 있거든. 여행자는 힘이 세니까, 반죽 담당."},{"id":"EVT_SEOLLAL_TRV_1_024","t":"narr","who":"","text":"이세계인이 웃으며 앞장선다. 낯선 장식이 흔들리는 골목 안쪽에서, 향릉의 목소리와 누룽지의 울음소리가 들려온다."}]},"EVT_SEOLLAL_TRV_2":{"festival":"SEOLLAL","route":"TRV","part":2,"title":"세배를 배우는 여행자","map":"MAP_LY_DETAIL_NORTH_GATE","items":[{"t":"scene","name":"왕생당"},{"id":"EVT_SEOLLAL_TRV_2_001","t":"narr","who":"","text":"왕생당 앞마당. 이세계인이 마당 한가운데에서 절하는 시늉을 하고, 호두와 중운이 따라 한다. 여행자와 페이몬은 그 모습을 구경하는 중이다."},{"id":"EVT_SEOLLAL_TRV_2_002","t":"line","who":"이세계인","text":"손은 겹쳐서 이마에, 무릎 꿇고, 천천히. 일어날 때도 천천히. 이게 세배야. 그러면 어른이 세뱃돈을 줘."},{"id":"EVT_SEOLLAL_TRV_2_003","t":"line","who":"페이몬","text":"절만 하면 모라를 준다고?! 여행자, 우리 지금 당장 배워야 해!"},{"t":"choice","group":"EVT_SEOLLAL_TRV_2_C1","opts":[{"id":"EVT_SEOLLAL_TRV_2_004","label":"페이몬은 떠 있잖아. 무릎을 어떻게 꿇어?","items":[{"id":"EVT_SEOLLAL_TRV_2_005","t":"line","who":"페이몬","text":"…떠 있는 채로 꿇으면 되잖아! 봐, 이렇게!"}]},{"id":"EVT_SEOLLAL_TRV_2_006","label":"누구한테 절하려고?","items":[{"id":"EVT_SEOLLAL_TRV_2_007","t":"line","who":"페이몬","text":"모라가 많은 사람한테!"}]}]},{"id":"EVT_SEOLLAL_TRV_2_008","t":"line","who":"호두","text":"히히, 둘 다 마음에 드는데? 이 당주님은 호두야. 왕생당 당주. 처음 보는 얼굴인데, 혹시 다음 손님?"},{"id":"EVT_SEOLLAL_TRV_2_009","t":"say","who":"주인공","text":"아직은 살아 있는 손님이야."},{"id":"EVT_SEOLLAL_TRV_2_010","t":"line","who":"호두","text":"아쉽다. 그럼 아직 손님 아닌 사람으로 대접해 줄게."},{"t":"scene","name":"문가의 손님"},{"id":"EVT_SEOLLAL_TRV_2_011","t":"line","who":"종려","text":"바람에 다른 냄새가 섞여 있다 했더니… 자네들이었군."},{"id":"EVT_SEOLLAL_TRV_2_012","t":"narr","who":"","text":"왕생당 문가에 종려가 서 있다. 그는 여행자를 오래 바라본다. 처음 보는 사람을 보는 눈이 아니다. 아주 오래된 무언가를 확인하는 눈이다."},{"id":"EVT_SEOLLAL_TRV_2_013","t":"line","who":"종려","text":"이 세상 사람이 아니로군. 그렇다고 해롭지도 않고. 새해를 맞으러 먼 데서 온 손님이라 여기겠네."},{"t":"choice","group":"EVT_SEOLLAL_TRV_2_C2","opts":[{"id":"EVT_SEOLLAL_TRV_2_014","label":"우리를 알아요?","items":[{"id":"EVT_SEOLLAL_TRV_2_015","t":"line","who":"종려","text":"모르네. 다만 길을 잃은 사람의 걸음은 어디서든 비슷하지."}]},{"id":"EVT_SEOLLAL_TRV_2_016","label":"…돌아가는 방법을 알아요?","items":[{"id":"EVT_SEOLLAL_TRV_2_017","t":"line","who":"종려","text":"오는 길이 있었다면 가는 길도 있겠지. 서두르지 말게. 길은 대개 문을 닫을 때가 아니라 열 때 보이니."}]}]},{"id":"EVT_SEOLLAL_TRV_2_018","t":"line","who":"이세계인","text":"종려 씨, 마침 잘 오셨어요. 연습 상대가 필요했거든요. 다 같이 한 번 해 보자."},{"id":"EVT_SEOLLAL_TRV_2_019","t":"narr","who":"","text":"넷이 나란히 선다. 여행자, 중운, 호두, 그리고 반쯤 떠 있는 페이몬. 천천히 절을 올린다. 종려는 고개를 끄덕이고, 소매 안을 더듬는다."},{"id":"EVT_SEOLLAL_TRV_2_020","t":"line","who":"종려","text":"…지갑을 두고 왔군."},{"id":"EVT_SEOLLAL_TRV_2_021","t":"line","who":"페이몬","text":"에에?! 절 다 했는데!"},{"id":"EVT_SEOLLAL_TRV_2_022","t":"line","who":"이세계인","text":"괜찮아. 설날엔 덕담이라는 게 있어. 돈 대신 좋은 말을 해 주는 거야."},{"id":"EVT_SEOLLAL_TRV_2_023","t":"line","who":"종려","text":"덕담이라면 할 수 있지. 먼 데서 온 손님에게는 —"},{"id":"EVT_SEOLLAL_TRV_2_024","t":"line","who":"종려","text":"찾는 사람이 있다면, 그 사람도 같은 하늘 아래에서 자네를 찾고 있기를."},{"id":"EVT_SEOLLAL_TRV_2_025","t":"narr","who":"","text":"여행자가 잠깐 숨을 멈춘다. 페이몬이 옆에서 조용히 여행자의 소매를 붙잡는다."},{"id":"EVT_SEOLLAL_TRV_2_026","t":"line","who":"페이몬","text":"…여행자."},{"id":"EVT_SEOLLAL_TRV_2_027","t":"say","who":"주인공","text":"고마워요. 그 말, 모라보다 좋네요."},{"id":"EVT_SEOLLAL_TRV_2_028","t":"line","who":"호두","text":"좋아, 결정! 모라는 이 당주님이 줄게. 대신 다음엔 왕생당 홍보 좀 해 줘. 다른 세계에서도!"}]},"EVT_SEOLLAL_TRV_3":{"festival":"SEOLLAL","route":"TRV","part":3,"title":"떡국과 돌아가는 길","map":"MAP_LY_DETAIL_CHIHU","items":[{"t":"scene","name":"만민당의 밤"},{"id":"EVT_SEOLLAL_TRV_3_001","t":"narr","who":"","text":"만민당 앞에 탁자가 붙었다. 하얀 국물 위에 얇은 떡이 떠 있다. 여행자가 하루 종일 치댄 반죽이 그릇마다 담겼다."},{"id":"EVT_SEOLLAL_TRV_3_002","t":"line","who":"향릉","text":"다 됐다! 여행자가 반죽을 너무 세게 쳐서, 떡이 엄청 쫄깃해!"},{"id":"EVT_SEOLLAL_TRV_3_003","t":"line","who":"페이몬","text":"우와! 냄새 좋다! 이게 떡국이야? 한 그릇 먹으면 한 살?"},{"id":"EVT_SEOLLAL_TRV_3_004","t":"line","who":"이세계인","text":"응. 그러니까 조심해서 먹어."},{"id":"EVT_SEOLLAL_TRV_3_005","t":"narr","who":"","text":"페이몬이 세 그릇을 비웠다."},{"id":"EVT_SEOLLAL_TRV_3_006","t":"say","who":"주인공","text":"페이몬, 세 살 먹었어."},{"id":"EVT_SEOLLAL_TRV_3_007","t":"line","who":"페이몬","text":"나이는 안 먹는다구! 떡만 먹은 거야! …근데 진짜 맛있다."},{"id":"EVT_SEOLLAL_TRV_3_008","t":"line","who":"중운","text":"김이 빠질 때까지 기다리면 더 맛있어."},{"id":"EVT_SEOLLAL_TRV_3_009","t":"line","who":"행추","text":"그건 너만 그래."},{"id":"EVT_SEOLLAL_TRV_3_010","t":"narr","who":"","text":"웃음소리 사이로, 이세계인이 그릇을 내려놓고 항구 쪽을 본다. 바다 위 하늘이 이상하게 하얗다."},{"id":"EVT_SEOLLAL_TRV_3_011","t":"line","who":"이세계인","text":"…너희 올 때도 저랬어?"},{"id":"EVT_SEOLLAL_TRV_3_012","t":"say","who":"주인공","text":"응. 저 빛이야."},{"id":"EVT_SEOLLAL_TRV_3_013","t":"line","who":"페이몬","text":"벌써?! 아직 덕담도 다 못 들었는데!"},{"t":"scene","name":"복주머니"},{"id":"EVT_SEOLLAL_TRV_3_014","t":"line","who":"이세계인","text":"그럼 빨리 해야겠다. 잠깐만."},{"id":"EVT_SEOLLAL_TRV_3_015","t":"narr","who":"","text":"이세계인이 품에서 작은 비단 주머니를 꺼낸다. 붉은 바탕에 서툰 바느질로 글자 하나가 수놓아져 있다."},{"id":"EVT_SEOLLAL_TRV_3_016","t":"line","who":"이세계인","text":"복주머니야. 내 고향에선 설날에 이걸 줘. 복 담아 가라고. 바느질은… 내가 했어. 보지 마."},{"t":"choice","group":"EVT_SEOLLAL_TRV_3_C1","opts":[{"id":"EVT_SEOLLAL_TRV_3_017","label":"고마워. 너는 돌아가는 방법 찾았어?","items":[{"id":"EVT_SEOLLAL_TRV_3_018","t":"line","who":"이세계인","text":"아니. 근데 괜찮아. 여기도 이제 꽤 집 같거든. 떡국도 있고."}]},{"id":"EVT_SEOLLAL_TRV_3_019","label":"너도 집에 가고 싶지 않아?","items":[{"id":"EVT_SEOLLAL_TRV_3_020","t":"line","who":"이세계인","text":"가고 싶지. 근데 오늘은 여기서 한 살 먹었으니까, 올해는 여기서 살아 보려고."}]}]},{"id":"EVT_SEOLLAL_TRV_3_021","t":"line","who":"이세계인","text":"여행자. 새해 복 많이 받아. 찾는 사람, 꼭 찾아."},{"id":"EVT_SEOLLAL_TRV_3_022","t":"say","who":"주인공","text":"너도. 새해 복 많이 받아."},{"id":"EVT_SEOLLAL_TRV_3_023","t":"line","who":"페이몬","text":"새해 복 많이 받아! 떡국 고마웠어! 다음에 또 줘!"},{"id":"EVT_SEOLLAL_TRV_3_024","t":"narr","who":"","text":"빛이 번진다. 향릉이 손을 흔들고, 호두가 무언가를 외친다. 소리가 멀어진다."},{"t":"scene","name":"원래의 길"},{"id":"EVT_SEOLLAL_TRV_3_025","t":"narr","who":"","text":"눈을 뜬다. 처음 빛이 났던 그 길 위다. 바람이 다시 분다. 어디에도 붉은 등은 없다."},{"id":"EVT_SEOLLAL_TRV_3_026","t":"line","who":"페이몬","text":"…꿈이었나? 떡국 맛이 아직 입에 남아 있는데."},{"id":"EVT_SEOLLAL_TRV_3_027","t":"narr","who":"","text":"여행자의 손에 작은 비단 주머니가 쥐여 있다. 서툰 바느질의 글자 하나. 복(福)."},{"id":"EVT_SEOLLAL_TRV_3_028","t":"say","who":"주인공","text":"꿈 아니야."},{"id":"EVT_SEOLLAL_TRV_3_029","t":"line","who":"페이몬","text":"헤헤… 그치? 그럼 우리도 올해는 복 많이 받는 거다!"}]}}};
